// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {CDPVault} from "src/CDPVault.sol";
import {Parameters} from "src/Parameters.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {SwarmWorkOracle} from "src/SwarmWorkOracle.sol";
import {WorkOracleFactory} from "src/WorkOracleFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {
    APPROVED_OPERATOR, TREASURY_FACTORY, WORK_ORACLE_FACTORY,
    WORK_ORACLE_SENTINEL, CHAINLINK_ETH_USD, ERC8004_ADAPTER
} from "src/DeploymentConfig.sol";

contract AuditIMD is ERC20 {
    constructor() ERC20("IMD", "IMD") {}
    function mint(address to, uint256 amount) external { _mint(to, amount); }
}

contract AuditShare is ERC20 {
    IERC20 public immutable asset;
    constructor(IERC20 token) ERC20("sIMD", "sIMD") { asset = token; }
    function decimals() public pure override returns (uint8) { return 24; }
    function convertToAssets(uint256 shares) public pure returns (uint256) {
        return shares * 7.95e12 / 1e18;
    }
    function deposit(uint256 amount, address to) external returns (uint256 shares) {
        asset.transferFrom(msg.sender, address(this), amount);
        shares = amount * 1e18 / 7.95e12;
        _mint(to, shares);
    }
}

contract AuditFreshFeed is ISwarmFeed {
    uint256 private immutable value;
    constructor(uint256 v) { value = v; }
    function latestValue() external view returns (uint256, uint64) {
        return (value, uint64(block.timestamp));
    }
    function maxAge() external pure returns (uint256) { return 1 days; }
    function isStale() external pure returns (bool) { return false; }
}

contract AuditUsd {
    function decimals() external pure returns (uint8) { return 8; }
    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

// Only the attestation fixture is substituted: claim/rights/consume/wage remain production code.
contract AuditSeededWork is SwarmWorkOracle {
    constructor(address v, uint256 age) SwarmWorkOracle(v, age) {}
    function seed(bytes32 root) external { _accept(uint256(root), uint64(block.timestamp)); }
}

contract AuditWorkFactory {
    function create(uint256 age) external returns (SwarmWorkOracle) {
        return new AuditSeededWork(msg.sender, age);
    }
}

contract GovernanceResidualRightsTest is Test {
    ParameterizedVault private vault;
    Parameters private params;
    AuditSeededWork private work;
    AuditIMD private imd;
    AuditShare private share;
    address private constant WORKER = address(0xCA);

    function setUp() public {
        vm.warp(1_000_000);
        vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(WORK_ORACLE_FACTORY, address(new AuditWorkFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new AuditUsd()).code);
        imd = new AuditIMD();
        share = new AuditShare(IERC20(address(imd)));
        vault = new ParameterizedVault(
            address(share), address(0), WORK_ORACLE_SENTINEL,
            address(new AuditFreshFeed(5e14)), address(new AuditFreshFeed(0.85e18)),
            address(new AuditFreshFeed(5e14))
        );
        params = vault.parameters();
        work = AuditSeededWork(address(vault.oracle()));
        _wage(1e18);
        bytes32 root = keccak256(bytes.concat(keccak256(abi.encode(uint256(7), uint32(500), uint64(500)))));
        work.seed(root);
        work.recordRoot();
        vm.mockCall(ERC8004_ADAPTER, abi.encodeWithSignature("isController(uint256,address)", 7, WORKER), abi.encode(true));
        vm.prank(WORKER);
        work.claim(7, 500, 500, new bytes32[](0), root);
        assertEq(work.mintingRights(WORKER), 500e18);
        _wage(0);
    }

    function _wage(uint256 rate) private {
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(rate);
        vm.warp(params.pendingEta());
        params.applyPending();
    }

    function test_zeroWageMustNotDisableBackingLagForOutstandingRights() public {
        assertEq(params.wage(), 0);
        assertEq(vault.totalEarned(), 0);
        imd.mint(WORKER, 2000e18);
        vm.startPrank(WORKER);
        imd.approve(address(vault), 2000e18);
        vault.lockIMD(2000e18);
        vault.draw(1000e18);
        vm.stopPrank();
        (uint256 lagDebt,) = vault.laggedNow();
        assertEq(lagDebt, 0, "fresh debt has not warmed up");

        // isolate=true gives each top-level call its own transaction, in the SAME block.
        // Allow either a zero-wage mint guard or an unconditional backing lag as the fix.
        vm.prank(WORKER);
        (bool minted,) = address(vault).call(abi.encodeCall(CDPVault.earn, (250e18)));
        minted;
        vm.startPrank(WORKER);
        vault.wipe(1000e18);
        (uint256 locked,) = vault.positions(WORKER);
        vault.free(locked);
        vm.stopPrank();
        assertEq(vault.totalDebt(), 0);
        assertEq(share.balanceOf(address(vault)), 0);
        assertEq(share.balanceOf(address(vault.treasury())), 0);
        assertEq(vault.stablecoin().totalSupply(), 0, "fresh temporary debt must not leave unbacked work supply");
    }

}

