contract ReturnDataReserve is ERC20 {
    constructor() ERC20("Reserve", "RSV") { _mint(msg.sender, 100e18); }
}

contract ReturnDataFeed {
    bool public broken;
    function fail() external { broken = true; }
    function isStale() external view returns (bool) {
        if (broken) {
            assembly {
                mstore(0, 0)
                return(0, 0x200000)
            }
        }
        return false;
    }
    function latestValue() external view returns (uint256, uint64) {
        return (1e18, uint64(block.timestamp));
    }
}

contract ReserveReturnDataTest is Test {
    function parameters() external view returns (address) { return address(this); }
    function gem() external pure returns (address) { return address(0x1234); }
    function stablecoin() external pure returns (address) { return address(0x5678); }

    function test_brokenFeedMustNotRevertTheEntireReserveRead() public {
        Treasury treasury = new Treasury(address(this));
        ReturnDataReserve token = new ReturnDataReserve();
        ReturnDataFeed feed = new ReturnDataFeed();
        token.transfer(address(treasury), 100e18);
        treasury.setReserveAsset(IERC20(address(token)), ISwarmFeed(address(feed)), 10_000);
        assertEq(treasury.reserveValueUsd(), 100e18);
        feed.fail();
        (bool ok,) = address(treasury).staticcall{gas: 16_000_000}(abi.encodeCall(Treasury.reserveValueUsd, ()));
        assertTrue(ok, "a broken feed must count for zero instead of exhausting the caller's memory-copy gas");
    }
}

