pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {CDPVault} from "src/CDPVault.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {MockIMD} from "src/MockIMD.sol";
import {MockWorkOracle} from "src/MockWorkOracle.sol";
import {Parameters} from "src/Parameters.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

/// @dev A never-stale swarm feed with a settable value.
contract ProofFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract ProofMirror is ISwarmFeed {
    ISwarmFeed private immutable primary;

    constructor(ISwarmFeed p) {
        primary = p;
    }

    function latestValue() external view returns (uint256, uint64) {
        return primary.latestValue();
    }

    function isStale() external view returns (bool) {
        return primary.isStale();
    }

    function maxAge() external view returns (uint256) {
        return primary.maxAge();
    }
}

/// @dev ETH/USD = $1.00 (8 decimals), always dated now: etched code carries no storage, so constants only.
contract ProofAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 1e8, block.timestamp, block.timestamp, 1);
    }
}

/// @notice Minting from work at wage 0. The wage is documented as the on/off switch for minting from
/// work, and `ParameterizedVault._lagApplies` turns the D1 lagged work ceiling on only while it is
/// nonzero. But rights credited while the wage was on survive it being set back to 0 (SwarmWorkOracle
/// prices rights at claim and `consumeRights`/`earn` never read the wage), so a rights holder can mint
/// against debt opened one block earlier with the lag off: exactly the D1 round trip the lag closes.
contract EarnAtZeroWageSkipsLagTest is Test {
    address private constant BORROWER = address(0xB0);
    address private constant WORKER = address(0xC0);

    MockIMD private imd;
    ParameterizedVault private vault;
    Parameters private parameters;
    ImdUSD private stable;
    MockWorkOracle private workOracle;

    function setUp() public {
        vm.warp(1_000_000);
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ProofAggregator()).code);
        imd = new MockIMD();
        ProofFeed primary = new ProofFeed(1 ether); // 1 ETH per IMD, ETH = $1: one dollar per IMD
        ProofFeed nhi = new ProofFeed(0.85 ether); // mat 170
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(nhi), address(new ProofMirror(primary))
        );
        parameters = vault.parameters();
        stable = vault.stablecoin();
        workOracle = MockWorkOracle(address(vault.oracle()));

        // Governance turns minting from work on (48 h), rights are credited while it is on, then
        // governance turns it off again (48 h). The rights stay where they are.
        _setWage(1 ether);
        vm.prank(APPROVED_OPERATOR);
        workOracle.grantRights(WORKER, 1_000 ether); // stands in for SwarmWorkOracle.claim at wage 1
        _setWage(0);
        assertEq(parameters.wage(), 0, "minting from work is documented OFF");
        assertEq(vault.totalEarned(), 0);
        assertEq(vault.totalDebt(), 0);
    }

    function _setWage(uint256 wad) private {
        vm.prank(APPROVED_OPERATOR);
        parameters.proposeWage(wad);
        vm.warp(parameters.pendingEta());
        parameters.applyPending();
    }

    function test_earnAtZeroWageAgainstDebtOpenedOneBlockEarlierIsRefused() public {
        // tx 1: a fresh position opens 200 imdUSD of debt. Nothing else backs the vault.
        vm.prank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 400 ether);
        vm.startPrank(BORROWER);
        imd.approve(address(vault), 400 ether);
        vault.lock(400 ether);
        vault.draw(200 ether);
        vm.stopPrank();

        // One block later.
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 12);

        // tx 2: the rights holder mints a quarter of that debt from work.
        // EXPECTED: refused. Either the wage-0 "off" switch refuses minting from work, or the D1 lag
        // applies and the ceiling is reserve (0) + 25% of the WARMED debt (200e18 * 12 s / 1 day), so
        // 50e18 is far above it and `earn` reverts WorkCeilingReached.
        // ACTUAL on the committed code: `_lagApplies()` is false at wage 0, backedDebt() counts the
        // whole 200e18 opened in the previous block, earnLine() is exactly 50e18 and earn succeeds.
        vm.prank(WORKER);
        (bool ok,) = address(vault).call(abi.encodeCall(CDPVault.earn, (50 ether)));
        assertFalse(ok, "earn at wage 0 against one-block-old debt must be refused (wage switch or D1 lag)");
    }
}

