contract WZAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @notice The lagged work ceiling (the D1 fix) is read only while `parameters.wage() != 0`, but
/// `earn` consumes rights whatever the wage is. Rights claimed while a wage was in force survive the
/// wage being set back to zero (the state `proposeWorkOracle` requires), and in that state the D1
/// round trip is open again: borrow in one block, earn against a quarter of it in the next, unwind.
contract WageZeroLagOffTest is Test {
    address private constant WORKER = address(0xCA);
    address private constant HELPER = address(0x4E1);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    MockWorkOracle private oracle;
    Parameters private params;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new WZAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        // 1 IMD = 1/2000 ETH and 1 ETH = $2000: the vault prices IMD at exactly $1.
        WZFeed primary = new WZFeed(uint256(1 ether) * 1e18 / 2000 ether);
        WZFeed health = new WZFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new WZMirror(primary))
        );
        stable = vault.stablecoin();
        oracle = MockWorkOracle(address(vault.oracle()));
        params = vault.parameters();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(WORKER, 2_000 ether);
        imd.mint(HELPER, 200 ether);
        vm.stopPrank();
        vm.prank(WORKER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(HELPER);
        imd.approve(address(vault), type(uint256).max);
    }

    function _setWage(uint256 wad) private {
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(wad);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
        assertEq(params.wage(), wad);
    }

    function _nextBlock() private {
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 12);
    }

    function test_rightsClaimedUnderAWageAreMintedUnlaggedOnceTheWageIsZero() public {
        // Minting from work was on; an agent claimed rights (priced at claim, kept in the oracle).
        _setWage(0.01 ether);
        vm.prank(APPROVED_OPERATOR);
        oracle.grantRights(WORKER, 1_000 ether);
        // Governance turns the wage back to zero (required before any proposeWorkOracle). Rights stay.
        _setWage(0);
        assertEq(oracle.mintingRights(WORKER), 1_000 ether, "rights survive the wage going to zero");

        // The D1 round trip, one block apart: borrow, then earn against a quarter of that debt.
        vm.startPrank(WORKER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        _nextBlock();

        // Expected, per ParameterizedVault.backedDebt / test/LaggedBacking.t.sol: debt one block old
        // earns about 0.014% of its credit, so a 250 imdUSD earn is refused (WorkCeilingReached).
        // Actual: `_lagApplies()` is false at wage 0, earnLine reads the live 1_000 * 25% = 250, and the
        // earn succeeds.
        vm.prank(WORKER);
        vm.expectRevert();
        vault.earn(250 ether);
        assertEq(vault.totalEarned(), 0, "no work-minted imdUSD against one-block-old debt");

        // Unwind to show what the lag was protecting: work-minted imdUSD outliving the debt behind it.
        // (A helper position supplies the 12 seconds of stability fee the worker owes.)
        vm.startPrank(HELPER);
        vault.lock(200 ether);
        vault.draw(50 ether);
        stable.transfer(WORKER, 50 ether);
        vm.stopPrank();
        vm.startPrank(WORKER);
        vault.wipe(vault.debtOf(WORKER));
        vault.free(2_000 ether);
        vm.stopPrank();
        assertEq(vault.totalDebt(), 50 ether, "only the helper's debt remains");
        assertEq(vault.totalEarned(), 0, "nothing minted from work outlives the debt that authorised it");
    }
}
